// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Properties;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LegacyStorePropertiesTest {

	@TempDir
	Path dataDir;

	@Test
	void loadsAndPreservesThe53MetadataLayout() throws Exception {
		writeLegacyMetadata("5.3.2", "spoc,posc");

		LegacyStoreProperties properties = LegacyStoreProperties.open(dataDir.toFile());
		assertTrue(properties.isLoaded());
		assertTrue(properties.isLegacy());
		assertEquals("5.3.2", properties.getVersion());
		assertEquals("spoc,posc", properties.getTripleIndexes());
		assertFalse(Files.exists(dataDir.resolve(StoreProperties.FILE_NAME)));

		properties.setTripleIndexes("spoc,posc,ospc");
		properties.save();

		Properties reloaded = new Properties();
		try (var in = Files.newInputStream(dataDir.resolve("triples").resolve("triples.prop"))) {
			reloaded.load(in);
		}
		assertEquals("1", reloaded.getProperty("version"));
		assertEquals("spoc,posc,ospc", reloaded.getProperty("triple-indexes"));
		assertFalse(Files.exists(dataDir.resolve(StoreProperties.FILE_NAME)));
	}

	@Test
	void accepts53SnapshotAndQualifierVersions() throws Exception {
		writeLegacyMetadata("5.3.0-SNAPSHOT", "spoc,posc");
		assertEquals("5.3.0-SNAPSHOT", LegacyStoreProperties.open(dataDir.toFile()).getVersion());

		Files.writeString(dataDir.resolve("lmdbrdf.ver"), "5.3-SNAPSHOT", StandardCharsets.UTF_8);
		assertEquals("5.3-SNAPSHOT", LegacyStoreProperties.open(dataDir.toFile()).getVersion());
	}

	@Test
	void rejectsNon53Stores() throws Exception {
		writeLegacyMetadata("5.2.4", "spoc,posc");
		assertThrows(IOException.class, () -> LegacyStoreProperties.open(dataDir.toFile()));
	}

	private void writeLegacyMetadata(String version, String indexes) throws IOException {
		Files.writeString(dataDir.resolve("lmdbrdf.ver"), version, StandardCharsets.UTF_8);
		Path triples = Files.createDirectories(dataDir.resolve("triples"));
		Properties properties = new Properties();
		properties.setProperty("version", "1");
		properties.setProperty("triple-indexes", indexes);
		try (OutputStream out = Files.newOutputStream(triples.resolve("triples.prop"))) {
			properties.store(out, "test");
		}
	}
}
